/**
 * The payment methods offered in the picker. Ids are Adyen txvariants, which is
 * what the vendored logo files are keyed by.
 *
 * Generated by scripts/fetch-payment-logos.mjs — do not edit by hand.
 */

export const METHOD_GROUPS = [
  { id: 'cards', label: 'Cards' },
  { id: 'wallets', label: 'Wallets' },
  { id: 'banking', label: 'Bank transfer and debit' },
  { id: 'bnpl', label: 'Buy now, pay later' },
  { id: 'local', label: 'Local favourites' },
] as const;

export type MethodGroupId = (typeof METHOD_GROUPS)[number]['id'];

export interface PaymentMethodSpec {
  readonly id: string;
  readonly label: string;
  readonly group: MethodGroupId;
}

