const BY_ID = new Map(PAYMENT_METHODS.map((method) => [method.id, method] as const));

export function paymentMethodSpec(id: string): PaymentMethodSpec | null {
  return BY_ID.get(id) ?? null;
}

export function isPaymentMethodId(value: unknown): value is string {
  return typeof value === 'string' && BY_ID.has(value);
}

export function methodLabel(id: string): string {
  return BY_ID.get(id)?.label ?? id;
}
